entries.syntax_block:
Connection = New HTTPConnection(host, port, user, password, timeout);
Connection.Host   Connection.Port   Connection.Timeout = seconds;

try {
    Response = Connection.Get(Request);          // Post  Put  Patch  Delete  Head
    Response = Connection.CallMethod(HTTPMethod.Options, Request);
} except {
    Message(ErrorDescription());                 // no answer at all
}

