entries.example:
Connection = New HTTPConnection("api.example", 8080, "user", "password", 30);
Request = New HTTPRequest("/v1/sales?shift=42");
Request.Headers.Insert("Accept", "application/json");

try {
    Response = Connection.Get(Request);
    if (Response.StatusCode = 200) {            // 404 и 500 — ОТВЕТЫ, а не отказы
        Message(Response.GetBodyAsString());
    } else {
        Message("ответил " + Response.StatusCode);
    }
} except {
    Message("ответа нет: " + ErrorDescription());   // имя не разрешилось, порт закрыт или прошло 30 с
}

