Data = New BinaryData();
Data.Read("C:\out\receipt.pdf");
Request.Headers.Insert("Content-Type", "application/pdf");
Request.SetBodyFromBinaryData(Data);

Response = Connection.Get(Request);
if (Response.StatusCode = 200) {
    Message(Response.GetBodyAsString());
} elseif (Response.StatusCode = 302) {
    Message("переехало на " + Response.Headers["Location"]);
} else {
    Message("ответил " + Response.StatusCode);
}

